// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/timelock.sol";

contract TimeLockTest is Test {
    TimeLock timelock;
    address alice = address(0x100);
    address bob = address(0x101);
    uint256 constant LOCK_PERIOD = 1 weeks;

    function setUp() public {
        vm.deal(alice, 2 ether);
        vm.deal(bob, 2 ether);
        timelock = new TimeLock();
    }

    function testTimestampManipulationVulnerability() public {
        // Alice makes deposit at initial timestamp
        vm.warp(1000);
        vm.prank(alice);
        timelock.deposit{value: 1 ether}();

        // Verify Alice's deposited balance
        assertEq(alice.balance, 1 ether, "Alice balance after deposit");
        assertEq(address(timelock).balance, 1 ether, "Contract balance after Alice deposit");

        // Alice withdraws after lock period
        vm.warp(1000 + LOCK_PERIOD + 1);
        vm.prank(alice);
        timelock.withdraw();

        // Verify Alice's final balance
        assertEq(alice.balance, 2 ether, "Alice balance after withdrawal");
        assertEq(address(timelock).balance, 0, "Contract balance after Alice withdrawal");

        // Bob deposits at different timestamp
        vm.warp(3000);
        vm.prank(bob);
        timelock.deposit{value: 1 ether}();

        // Bob attempts early withdrawal (should fail)
        vm.warp(3000 + LOCK_PERIOD - 1);
        vm.prank(bob);
        vm.expectRevert("Funds are still locked");
        timelock.withdraw();

        // Bob successfully withdraws after lock period
        vm.warp(3000 + LOCK_PERIOD + 1);
        vm.prank(bob);
        timelock.withdraw();

        // Verify final balances
        assertEq(bob.balance, 2 ether, "Bob balance after withdrawal");
        assertEq(address(timelock).balance, 0, "Contract final balance");
    }
}
