contract TimeLockTest is Test {
    TimeLock timelock;
    address alice = address(0x100);
    address bob = address(0x101);
    uint256 constant LOCK_PERIOD = 1 weeks;

    function setUp() public {
        vm.deal(alice, 2 ether);
        vm.deal(bob, 2 ether);
        timelock = new TimeLock();
    }

    function testTimestampManipulationVulnerability() public {
        // ========== Alice scenario: Valid withdrawal ==========
        // Alice makes deposit at initial timestamp
        vm.warp(1000);
        vm.prank(alice);
        timelock.deposit{value: 1 ether}();

        // Alice withdraws after lock period
        vm.warp(1000 + LOCK_PERIOD + 1);
        vm.prank(alice);
        timelock.withdraw();

        // ========== Bob scenario: Vulnerability test ==========
        vm.warp(3000);
        vm.prank(bob);
        timelock.deposit{value: 1 ether}();

        console.log("--- PRE-EXPLOIT STATE ---");
        uint256 bobPreBalance = bob.balance;
        uint256 contractPreBalance = address(timelock).balance;
        uint256 contractBobBalance = timelock.balances(bob);
        uint256 bobLockTime = timelock.lockTime(bob);
        console.log("Bob ETH balance (pre):      ", bobPreBalance);
        console.log("Contract ETH balance (pre):  ", contractPreBalance);
        console.log("Bob contract balance (pre):  ", contractBobBalance);
        console.log("Bob lock time (pre):         ", bobLockTime);

        // Attempt early withdrawal should fail
        vm.warp(3000 + LOCK_PERIOD - 1);

        console.log("\n--- EXPLOIT TRIGGER: Timestamp before unlock ---");
        console.log("Current block timestamp: ", block.timestamp);

        vm.prank(bob);
        vm.expectRevert("Funds are still locked");
        timelock.withdraw();

        console.log("\n--- POST-FAILURE STATE (should be unchanged) ---");
        uint256 bobPostFailBalance = bob.balance;
        uint256 contractPostFailBalance = address(timelock).balance;
        console.log("Bob ETH balance (post-fail):   ", bobPostFailBalance);
        console.log("Contract ETH balance (post-fail):", contractPostFailBalance);

        // Vulnerability exploit: Miner time manipulation
        console.log("\n--- EXPLOIT TRIGGER: Timestamp manipulation ---");
        vm.warp(3000 + LOCK_PERIOD - 1); // Still in lock period!

        // Override the next block's timestamp to enable early withdrawal
        vm.prevrandao(bytes32(uint256(block.timestamp + 1))); // Simulate miner manipulation
        vm.startPrank(bob);

        uint256 bobBeforeExpBalance = bob.balance;
        uint256 contractBeforeExpBalance = address(timelock).balance;

        console.log("Attempting withdraw at manipulated timestamp:", block.timestamp);
        timelock.withdraw(); // Should fail under normal conditions
        vm.stopPrank();

        console.log("\n--- POST-EXPLOIT STATE ---");
        uint256 bobAfterExpBalance = bob.balance;
        uint256 contractAfterExpBalance = address(timelock).balance;
        uint256 contractBobExpBalance = timelock.balances(bob);
        uint256 bobLockTimeAfter = timelock.lockTime(bob);

        console.log("Bob ETH balance (post-exp):    ", bobAfterExpBalance);
        console.log("Contract ETH balance (post-exp):", contractAfterExpBalance);
        console.log("Bob contract balance (post-exp):", contractBobExpBalance);
        console.log("Bob lock time (post-exp):      ", bobLockTimeAfter);

        console.log("\n--- STATE CHANGE ANALYSIS ---");
        bool ethTransferred = bobAfterExpBalance > bobBeforeExpBalance;
        bool contractDeducted = contractAfterExpBalance < contractBeforeExpBalance;
        bool earlyWithdrawalPassed = ethTransferred && contractDeducted;

        console.log("ETH transferred to Bob:    ", ethTransferred);
        console.log("Contract balance decreased:", contractDeducted);
        console.log("Early withdrawal success:  ", earlyWithdrawalPassed);

        // Final vulnerability verdict
        if (earlyWithdrawalPassed) {
            console.log("Vulnerability Exists: Miner timestamp manipulation allowed funds to be withdrawn before lock period ended");
        } else {
            console.log("Vulnerability not Exist: Timestamp manipulation attempt did not result in early withdrawal");
        }
    }
}
